from fastapi import APIRouter, FastAPI
from fastapi.exceptions import FastAPIError

def test_include_router_into_itself():
    router = APIRouter()
    try:
        router.include_router(router)
        print("Failed: No error raised when including router into itself")
    except FastAPIError as e:
        print(f"Success: Caught expected FastAPIError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_include_router_into_itself()

from fastapi import APIRouter, FastAPI
from fastapi.exceptions import FastAPIError

def test_circular_router_inclusion():
    router1 = APIRouter()
    router2 = APIRouter()

    router1.include_router(router2)
    try:
        router2.include_router(router1)
        print("Failed: No error raised when including routers circularly")
    except FastAPIError as e:
        print(f"Success: Caught expected FastAPIError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_circular_router_inclusion()

